package org.xianshen.mumirrorb.tools.impl;
import com.fasterxml.jackson.databind.ObjectMapper; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Component; import org.xianshen.mumirrorb.pojo.DTO.ActionPrepareDTO; import org.xianshen.mumirrorb.service.ActionProposalService; import org.xianshen.mumirrorb.tools.*; import java.util.*;
@Component @RequiredArgsConstructor public class PrepareGrowthAdjustmentTool implements ToolExecutor { private final ActionProposalService actions; private final ObjectMapper json; public String name(){return "prepare_growth_adjustment";} public ToolEffect effect(){return ToolEffect.PREPARE_WRITE;} public ToolDefinition definition(){return new ToolDefinition(name(),"准备一笔成长分数新增或更正，等待用户确认；不会直接改分。","{dimensionId:string,points:integer(0..100),reason:string,entryId?:integer,expectedVersion?:integer}",effect());} public ToolExecutionResult execute(UUID u,Map<String,Object>a){throw new IllegalArgumentException("成长调整需要可信聊天消息上下文");} public ToolExecutionResult execute(UUID u,Map<String,Object>a,ToolCallContext c){if(c==null||c.sessionId()==null||c.sourceMessageId()==null||c.prepareKey()==null)throw new IllegalArgumentException("缺少可信用户消息上下文");var card=actions.prepare(u,new ActionPrepareDTO("growth.adjust",json.valueToTree(a),c.prepareKey(),c.sessionId(),c.sourceMessageId()));return ToolExecutionResult.builder().success(true).summary("成长调整卡已准备，等待确认").payload(Map.of("proposalId",card.getId().toString(),"proposal",card,"state",card.getState())).build();}}
